// 1. Input Validation
if (wd_input.wheel_count != 4) {
    wd_state.mode = WD_FAULT;
    wd_state.high_cycles = 0;
    wd_state.low_cycles = 0;
    wd_state.elapsed = 0;
    wd_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.parallel_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    wd_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.high_cycles = 0;
    wd_output.low_cycles = 0;
    wd_output.elapsed = 0;
    wd_output.saturation_mask = 0;
    return;
}

double b2 = adcs_vec3_dot(wd_input.field_body_t, wd_input.field_body_t);
if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM || !isfinite(b2)) {
    wd_state.mode = WD_FAULT;
    wd_state.high_cycles = 0;
    wd_state.low_cycles = 0;
    wd_state.elapsed = 0;
    wd_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.parallel_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    wd_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.high_cycles = 0;
    wd_output.low_cycles = 0;
    wd_output.elapsed = 0;
    wd_output.saturation_mask = 0;
    return;
}

if (!isfinite(wd_config.stop_nms) || !isfinite(wd_config.start_nms) || 
    wd_config.stop_nms >= wd_config.start_nms ||
    !isfinite(wd_config.max_wheel_speed_rad_s) || wd_config.max_wheel_speed_rad_s <= 0.0 ||
    !isfinite(wd_config.gain_s_inv) || wd_config.gain_s_inv < 0.0 ||
    !isfinite(wd_config.max_dipole_a_m2) || wd_config.max_dipole_a_m2 < 0.0 ||
    wd_config.required_high < 1 || wd_config.required_high > 100 ||
    wd_config.required_low < 1 || wd_config.required_low > 100 ||
    wd_config.minimum_dump_cycles < 1 || wd_config.minimum_dump_cycles > 100 ||
    wd_config.cooldown_cycles < 1 || wd_config.cooldown_cycles > 100 ||
    (wd_input.enable != 0 && wd_input.enable != 1)) {

    wd_state.mode = WD_FAULT;
    wd_state.high_cycles = 0;
    wd_state.low_cycles = 0;
    wd_state.elapsed = 0;
    wd_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.parallel_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    wd_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.high_cycles = 0;
    wd_output.low_cycles = 0;
    wd_output.elapsed = 0;
    wd_output.saturation_mask = 0;
    return;
}

// 2. Wheel Speed Check
for (size_t i = 0; i < 4; ++i) {
    if (fabs(wd_input.wheels[i].speed_rad_s) > wd_config.max_wheel_speed_rad_s) {
        wd_state.mode = WD_FAULT;
        wd_state.high_cycles = 0;
        wd_state.low_cycles = 0;
        wd_state.elapsed = 0;
        wd_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
        wd_output.parallel_momentum_nms = (adcs_vec3_t){0, 0, 0};
        wd_output.dumpable_momentum_nms = (adcs_vec3_t){0, 0, 0};
        wd_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
        wd_output.torque_nm = (adcs_vec3_t){0, 0, 0};
        wd_output.dumpable_magnitude_nms = 0.0;
        wd_output.high_cycles = 0;
        wd_output.low_cycles = 0;
        wd_output.elapsed = 0;
        wd_output.saturation_mask = 0;
        return;
    }
}

// 3. Compute Momentum
adcs_status_t status = adcs_wheel_momentum(wd_input.wheels, 4, &wd_output.momentum_nms);
if (status != ADCS_OK) {
     wd_state.mode = WD_FAULT;
     wd_state.high_cycles = 0;
     wd_state.low_cycles = 0;
     wd_state.elapsed = 0;
     wd_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
     wd_output.parallel_momentum_nms = (adcs_vec3_t){0, 0, 0};
     wd_output.dumpable_momentum_nms = (adcs_vec3_t){0, 0, 0};
     wd_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
     wd_output.torque_nm = (adcs_vec3_t){0, 0, 0};
     wd_output.dumpable_magnitude_nms = 0.0;
     wd_output.high_cycles = 0;
     wd_output.low_cycles = 0;
     wd_output.elapsed = 0;
     wd_output.saturation_mask = 0;
     return;
}

// 4. Decompose Momentum
double parallel_mag = adcs_vec3_dot(&wd_output.momentum_nms, wd_input.field_body_t) / b2;
wd_output.parallel_momentum_nms = adcs_vec3_scale(wd_input.field_body_t, parallel_mag);
wd_output.dumpable_momentum_nms = adcs_vec3_sub(&wd_output.momentum_nms, &wd_output.parallel_momentum_nms);
wd_output.dumpable_magnitude_nms = adcs_vec3_norm(&wd_output.dumpable_momentum_nms);

// 5. State Machine Transitions and Logic
switch (wd_state.mode) {
    case WD_OFF:
        if (wd_input.enable == 1) {
            wd_state.mode = WD_ARMING;
            // Entering ARMING does not require resetting counters per spec, 
            // but they are initialized to 0 at startup anyway.
        } else {
            wd_state.high_cycles = 0;
            wd_state.low_cycles = 0;
            wd_state.elapsed = 0;
        }
        break;

    case WD_ARMING:
        // Reset counters on entry to ARMING? Spec says entering DUMPING, COOLDOWN, OFF resets.
        // It doesn't mention ARMING. However, high_cycles needs to count consecutive samples.
        // If we just arrived from OFF, they should be 0.
        // If we were already in ARMING, we continue counting.
        // To be safe and clean, we can assume they are maintained across calls unless reset.
        // But since we don't reset them here, if we came from OFF (where we reset), they are 0.
        // If we stayed in ARMING, they persist. This is correct.

        if (wd_output.dumpable_magnitude_nms >= wd_config.start_nms) {
            wd_state.high_cycles++;
        } else {
            wd_state.high_cycles = 0;
        }

        if (wd_state.high_cycles >= wd_config.required_high) {
            wd_state.mode = WD_DUMPING;
            wd_state.elapsed = 0;
            wd_state.high_cycles = 0; // Reset on entry to DUMPING
            wd_state.low_cycles = 0;  // Reset on entry to DUMPING
        }
        break;

    case WD_DUMPING:
        wd_state.elapsed++;

        // Reset low_cycles logic
        if (wd_state.elapsed >= wd_config.minimum_dump_cycles) {
            if (wd_output.dumpable_magnitude_nms <= wd_config.stop_nms) {
                wd_state.low_cycles++;
            } else {
                wd_state.low_cycles = 0; // Clear low evidence
            }
        }

        if (wd_state.low_cycles >= wd_config.required_low) {
            wd_state.mode = WD_COOLDOWN;
            wd_state.elapsed = 0;
            wd_state.high_cycles = 0; // Reset on entry to COOLDOWN
            wd_state.low_cycles = 0;  // Reset on entry to COOLDOWN
        }
        break;

    case WD_COOLDOWN:
        wd_state.elapsed++;

        if (wd_state.elapsed >= wd_config.cooldown_cycles) {
            wd_state.mode = WD_OFF;
            wd_state.elapsed = 0;
            wd_state.high_cycles = 0;
            wd_state.low_cycles = 0;
        }
        break;

    case WD_FAULT:
        // Stay in fault
        break;
}

// 6. Generate Commands
wd_output.saturation_mask = 0;
wd_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
wd_output.torque_nm = (adcs_vec3_t){0, 0, 0};

if (wd_state.mode == WD_DUMPING || wd_state.mode == WD_COOLDOWN) {
    adcs_actuator_command_t cmd;
    adcs_vec3_t torque;
    adcs_vec3_t error;

    if (wd_state.mode == WD_DUMPING) {
        error = wd_output.dumpable_momentum_nms;
    } else {
        error = (adcs_vec3_t){0, 0, 0};
    }

    status = adcs_momentum_unload_dipole(&error, wd_input.field_body_t, 
                                         wd_config.gain_s_inv, wd_config.max_dipole_a_m2, 
                                         &cmd, &torque);

    wd_output.dipole_a_m2 = cmd.command;
    wd_output.torque_nm = torque;
    wd_output.saturation_mask = cmd.saturated_axes;
}

// 7. Update Output Counters
wd_output.high_cycles = wd_state.high_cycles;
wd_output.low_cycles = wd_state.low_cycles;
wd_output.elapsed = wd_state.elapsed;
wd_output.mode = wd_state.mode;

